/* OMA ONE: самостоятельный образовательный демо-прототип; нет подключения к системам ОМА */
import {api} from './api.js';
import {S} from './state.js';
import {track,trackError} from './analytics.js';

const $=sel=>document.querySelector(sel);
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(Number(n)||0);
const enc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dt=s=>new Date(s).toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'});
const formatSum=n=>`${money(n)} BYN`;
const NAV=[['home','🏠','Главная'],['planner','✨','Решить задачу'],['catalog','🛍️','Каталог'],['projects','📋','Мои проекты'],['dna','🧬','OMA DNA'],['zerobuy','♻️','ZeroBuy'],['antifail','🛡️','AntiFail'],['domino','🧩','Domino'],['synccity','🏘️','SyncCity'],['proof','✅','Proof'],['forge','⚙️','OMA FORGE'],['pulse','💓','OMA PULSE'],['business','📊','Экономика'],['profile','👤','Мой дом'],['cart','🛒','Корзина']];
const FEATURE=[['zerobuy','♻️','ZeroBuy','Покупай только то, чего нет дома'],['antifail','🛡️','AntiFail','Находит несовместимые решения'],['domino','🧩','Domino','Сохраняет правильный порядок работ'],['synccity','🏘️','SyncCity','Объединяет заказы соседей'],['proof','✅','Proof','Сохраняет результат работ'],['dna','🧬','OMA DNA','Повторяет проверенные проекты'],['forge','⚙️','OMA FORGE','Превращает спрос в товарные комплекты'],['pulse','💓','OMA PULSE','Показывает повторяющиеся проблемы']];
const PRIMARY_VIEWS=['home','planner','catalog','projects'];
const PILOT_VIEWS=['more','business','profile','cart'];
const ALL_VIEWS=new Set([...NAV.map(item=>item[0]),'more']);
const initialParams=new URLSearchParams(location.search);
const nativeClient=initialParams.get('native')==='ios';
if(nativeClient)document.documentElement.classList.add('native-ios');
const requestedView=initialParams.get('view');if(ALL_VIEWS.has(requestedView))S.view=requestedView;
let modalReturnFocus=null;
async function ensureSession(){try{const result=await api('/auth/session');S.userId=result.user.id;}catch(error){if(error.status!==401)throw error;const config=await api('/auth/config');if(config.demo){const result=await api('/auth/demo','POST',{userId:S.userId});S.userId=result.user.id;}else if(config.oidc){location.assign('/api/v1/auth/oidc/start?returnTo=/');await new Promise(()=>{});}else throw new Error('Не настроен способ входа');}localStorage.setItem('oma-demo-user',S.userId);}
async function load(){S.data=await api('/bootstrap');S.userId=S.data.user.id;localStorage.setItem('oma-demo-user',S.userId);}
function notify(message,isError=false){const wrap=$('#toasts');const item=document.createElement('div');item.className=`toast ${isError?'error':''}`;item.setAttribute('role',isError?'alert':'status');item.textContent=message;wrap.append(item);setTimeout(()=>item.remove(),4300);}
function busyStart(){S.busy=true;$('#app')?.setAttribute('aria-busy','true');document.body.classList.add('is-busy');document.querySelectorAll('[data-busy]').forEach(e=>{e.disabled=true;e.setAttribute('aria-disabled','true');});}
function busyEnd(){S.busy=false;$('#app')?.setAttribute('aria-busy','false');document.body.classList.remove('is-busy');document.querySelectorAll('[data-busy]').forEach(e=>{e.disabled=false;e.removeAttribute('aria-disabled');});}
async function mutation(fn,success='Готово'){if(S.busy)return;busyStart();try{const result=await fn();await load();render();if(success)notify(success);return result;}catch(e){trackError(e,S.view);notify(e.message,true);console.error(e);}finally{busyEnd();}}
function viewUrl(view){const params=new URLSearchParams();if(view!=='home')params.set('view',view);if(nativeClient)params.set('native','ios');const query=params.toString();return query?`/?${query}`:'/';}
function changeView(view,{history=true}={}){if(!ALL_VIEWS.has(view))view='home';S.view=view;S.modal=null;if(history)window.history.pushState({view},'',viewUrl(view));window.scrollTo({top:0,behavior:'instant'});render();track('page_view',{view});requestAnimationFrame(()=>$('.main h1')?.focus());}
function card(inner,classes=''){return `<div class="card ${classes}">${inner}</div>`;}
function chip(label,type=''){return `<span class="pill ${type}">${enc(label)}</span>`;}
function action(name,label,cls='secondary',attr=''){return `<button type="button" class="btn ${cls}" data-action="${name}" ${attr}>${label}</button>`;}
function title(t,sub='',extra=''){return `<div class="page-heading"><div><h1 tabindex="-1">${t}</h1><p class="lead">${sub}</p></div>${extra}</div>`;}
function empty(icon,heading,description,button=''){return `<div class="empty"><div class="big">${icon}</div><h3>${heading}</h3><p>${description}</p>${button}</div>`;}
function sep(){return '<div class="separator"></div>';}
function sc(){return S.data.scenarios.find(x=>x.id===S.scenario)||S.data.scenarios[0];}
function getProduct(id){return S.data.products.find(x=>x.id===id);}
function badgeLine(a,b){return `<div class="layout-spread"><span class="muted small">${a}</span><strong class="small">${b}</strong></div>`;}
function navFor(id){return id==='more'?['more','◫','Все сервисы']:NAV.find(item=>item[0]===id);}
function side(){return `<aside class="sidebar" aria-label="Основная навигация"><div class="brand"><div class="brand-logo" aria-hidden="true">О<span>·</span></div><div><strong>OMA ONE</strong><small>СЕРВИС ЖИЗНИ ДОМА</small></div></div><nav><div class="nav-heading">Главное</div>${PRIMARY_VIEWS.map(id=>navitem(navFor(id))).join('')}<div class="nav-heading">Пилот</div>${PILOT_VIEWS.map(id=>navitem(navFor(id))).join('')}</nav><div class="sidebar-footer"><b><span class="status-dot ${S.online?'':'offline'}"></span> ${S.online?'Сервис доступен':'Нет сети'}</b><small>Production-пилот · демонстрационные каталог и операции</small></div></aside>`;}
function navitem(n){return `<button class="nav-item ${S.view===n[0]?'active':''}" data-view="${n[0]}" ${S.view===n[0]?'aria-current="page"':''}><span class="nav-emoji" aria-hidden="true">${n[1]}</span>${n[2]}</button>`;}
function mobileTop(){return `<header class="mobile-top"><div class="brand"><div class="brand-logo" aria-hidden="true">О<span>·</span></div><div><strong>OMA ONE</strong><small>${S.online?'В СЕТИ':'ОФЛАЙН'}</small></div></div><button data-view="cart" class="icon-btn" aria-label="Корзина, товаров: ${S.data.cart.length}">🛒 ${S.data.cart.length}</button></header>`;}
function mobileBottom(){const n=[navFor('home'),navFor('planner'),navFor('projects'),navFor('catalog'),['more','◫','Ещё']];return `<nav class="mobile-tabs" aria-label="Мобильная навигация">${n.map(x=>`<button data-view="${x[0]}" class="mobile-tab ${S.view===x[0]?'active':''}" ${S.view===x[0]?'aria-current="page"':''}><span class="symbol" aria-hidden="true">${x[1]}</span>${x[2]}</button>`).join('')}</nav>`;}
function topbar(){return `<header class="topbar"><div class="crumb">OMA ONE <span> / ${navFor(S.view)?.[2]||'Главная'}</span></div><div class="top-actions"><button class="quick-task" data-view="planner">✨ Решить задачу</button><button class="icon-btn" data-view="cart" aria-label="Корзина, товаров: ${S.data.cart.length}">🛒 ${S.data.cart.length}</button><button class="profile-button" data-view="profile" aria-label="Открыть профиль ${enc(S.data.user.name)}"><span class="avatar" aria-hidden="true">${enc(S.data.user.name.slice(0,1))}</span><span>${enc(S.data.user.name)}</span></button></div></header>`;}
function connectionBanner(){return S.online?'':`<div class="offline-banner" role="status"><span aria-hidden="true">◌</span><div><strong>Нет подключения к сети</strong><small>Можно просматривать уже загруженные экраны. Изменения станут доступны после восстановления связи.</small></div></div>`;}
function enhanceForms(){document.querySelectorAll('.form-group').forEach(group=>{const label=group.querySelector('label'),control=group.querySelector('input,select,textarea');if(label&&control?.id)label.htmlFor=control.id;});}
function render(){if(!S.data)return;const main={home:pageHome,planner:pagePlanner,catalog:pageCatalog,projects:pageProjects,dna:pageDna,zerobuy:pageZeroBuy,antifail:pageAntiFail,domino:pageDomino,synccity:pageSyncCity,proof:pageProof,forge:pageForge,pulse:pagePulse,business:pageBusiness,profile:pageProfile,cart:pageCart,more:pageMore}[S.view]||pageHome;
 $('#app').innerHTML=`${mobileTop()}<div class="app-layout">${side()}<main class="main" id="main-content" tabindex="-1">${connectionBanner()}${topbar()}${main()}</main></div>${mobileBottom()}<button class="floating-help" data-action="chat-toggle" aria-label="${S.chatOpen?'Закрыть помощника':'Открыть помощника OMA ONE'}" aria-expanded="${S.chatOpen}">✦</button>${S.chatOpen?chatPanel():''}${S.modal?modal(S.modal):''}`;
 document.body.classList.toggle('modal-open',Boolean(S.modal));
 enhanceForms();
 if(S.modal)requestAnimationFrame(()=>$('.modal [data-action="close-modal"]')?.focus());
}
function chatPanel(){return `<section class="chat-panel" role="dialog" aria-label="Помощник OMA ONE"><div class="chat-head"><div class="row-wrap"><div class="chat-avatar" aria-hidden="true">✦</div><div><strong>Помощник OMA ONE</strong><small>Правила + проверяемые расчёты</small></div></div><div><button class="chat-x" data-action="help" aria-label="О приложении">ⓘ</button><button class="chat-x" data-action="chat-toggle" aria-label="Закрыть помощника">✕</button></div></div><div class="chat-body" id="chat-body" role="log" aria-live="polite">${S.chatMessages.map(m=>`<div class="chat-bubble ${m.role==='user'?'out':'in'}">${enc(m.text)}</div>`).join('')}${S.chatTyping?'<div class="chat-bubble in">Подбираю ответ…</div>':''}</div><form id="chat-form" class="chat-form"><label class="sr-only" for="chat-message">Сообщение помощнику</label><input class="input" id="chat-message" maxlength="800" placeholder="Например: хочу обновить балкон" required><button class="btn sm" type="submit" aria-label="Отправить сообщение" ${S.chatTyping?'disabled':''}>➤</button></form><div class="chat-legal">AI может ошибаться · цены и наличие проверяются сервером</div></section>`;}
function modal(config){return `<div class="modal-backdrop" data-modal-backdrop><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="layout-spread"><h2 id="modal-title">${config.title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть диалог">✕</button></div><p>${config.text}</p>${config.body||''}<div class="modal-actions">${action('close-modal','Понятно','secondary')}</div></section></div>`;}
function pageHome(){const d=S.data,u=d.user,cartTotal=d.cart.reduce((a,x)=>a+x.quantity*x.product.price,0),completed=d.projects.filter(x=>x.status==='completed').length;
return `<section class="hero"><div><div class="eyebrow" style="color:#b6f3d9">ДОБРО ПОЖАЛОВАТЬ, ${enc(u.name.toUpperCase())} 👋</div><h1>Ваш дом заслуживает<br>умных решений.</h1><p>Расскажите, что хотите сделать. Мы поможем собрать комплект, предотвратить ошибки и сохранить результат.</p>${action('new-task','✨ &nbsp; Решить задачу','green hero-btn')}</div><div class="hero-art">🏡<i class="art-a">🌿</i><i class="art-b">🔧</i></div></section>
<div class="grid cols-4 top-gap">${[['🏠','Мой дом',u.kind+' · '+u.area+' м²'],['📋','Мои проекты',String(d.projects.length)+' всего · '+completed+' завершено'],['🛒','В корзине',formatSum(cartTotal)],['📍','Ваш город',u.city]].map(([i,l,val])=>card(`<div style="font-size:25px">${i}</div><div class="kpi-val" style="font-size:18px;margin:9px 0 6px">${enc(val)}</div><div class="kpi-label">${l}</div>`,'kpi-card')).join('')}</div>
<div class="section-title"><h2>С какой задачей поможем?</h2><button class="btn sm secondary" data-view="planner">Все задачи →</button></div>
<div class="task-cards">${d.scenarios.slice(0,6).map(s=>`<button class="task-card" data-action="choose-scenario" data-id="${s.id}"><span class="emoji" aria-hidden="true">${s.emoji}</span><b>${enc(s.title)}</b><small>${enc(s.subtitle)}</small></button>`).join('')}</div>
<div class="section-title"><h2>Интеллектуальная экосистема</h2><small>8 механизмов в одной платформе</small></div><div class="feature-grid">${FEATURE.map(([view,icon,name,desc])=>`<button class="feature-card" data-view="${view}"><span class="feature-icon">${icon}</span><strong>${name} ↗</strong><span>${desc}</span></button>`).join('')}</div>
<div class="section-title"><h2>Ваш следующий шаг</h2></div>${card(`<div class="layout-spread" style="gap:20px;flex-wrap:wrap"><div><div class="eyebrow">НОВАЯ ВОЗМОЖНОСТЬ</div><h2 style="margin:8px 0 10px">Дом с памятью — OMA DNA</h2><p class="lead" style="max-width:550px">Не начинайте с нуля: адаптируйте проверенные сценарии ремонта под параметры вашего жилья.</p></div>${action('open-dna','Посмотреть проекты →','secondary')}</div>`,'soft')}`;
}
function pagePlanner(){const d=S.data,s=sc(),plan=S.plan;return `${title('Решить задачу','Наш движок сравнит сценарии, учтёт ваши запасы, предупредит о рисках и подготовит товары для корзины.',chip('6 сценариев для демонстрации'))}
<div class="workarea"><div><div class="task-cards bottom-gap">${d.scenarios.map(x=>`<button class="task-card ${s.id===x.id?'active':''}" data-action="select-scenario" data-id="${x.id}" aria-pressed="${s.id===x.id}"><span class="emoji" aria-hidden="true">${x.emoji}</span><b>${enc(x.title)}</b><small>${enc(x.subtitle)}</small></button>`).join('')}</div>
${card(`<div class="eyebrow bottom-gap">НАСТРОЙТЕ ЗАДАЧУ</div><form id="plan-form"><div class="form-group bottom-gap"><label>Опишите, что хотите сделать</label><textarea class="textarea" id="task-text" maxlength="500" placeholder="Например: хочу повесить полку на бетонную стену...">${plan&&plan.scenarioId===s.id?enc(plan.task):enc(s.title)}</textarea></div><div class="form-grid"><div class="form-group"><label>Бюджет, BYN</label><input class="input" id="task-budget" type="number" min="50" max="150000" value="${plan&&plan.scenarioId===s.id?plan.budget:s.defaultBudget}" required></div><div class="form-group"><label>Площадь / объём</label><input class="input" id="task-area" type="number" min=".5" max="120" step=".5" value="${plan&&plan.scenarioId===s.id?plan.area:s.area}" required></div></div><div class="form-group top-gap"><label>Способ выполнения</label><select class="select" id="task-mode"><option value="diy" ${S.planMode==='diy'?'selected':''}>Самостоятельно</option><option value="hybrid" ${S.planMode==='hybrid'?'selected':''}>Комбинированный</option><option value="pro" ${S.planMode==='pro'?'selected':''}>С мастером</option></select></div><label class="switch-row top-gap"><input type="checkbox" id="task-risk" ${plan?.flagged?'checked':''}> Проверить подозрительный / неподходящий материал (демо AntiFail)</label><div class="form-actions"><button type="submit" class="btn" data-busy>✨ Рассчитать оптимальный план</button></div></form>`)}
${plan?renderPlan(plan):''}</div><div class="sticky">${card(`<div class="eyebrow bottom-gap">ВАШ УМНЫЙ ПОМОЩНИК</div><div class="banner"><div class="banner-emoji">🧠</div><div><strong>OMA Decision Engine</strong><p>Рассчитывает сценарии по правилам, а не придумывает несуществующие цены.</p></div></div>${sep()}<div class="small muted" style="line-height:1.8">✓ Материалы и количества<br>✓ ZeroBuy — учёт домашних запасов<br>✓ AntiFail — контроль совместимости<br>✓ Domino — зависимости работ<br>✓ Сценарии бюджета и услуги мастеров</div>${sep()}<p class="notice">AI-поставщик не подключён. Сейчас работает прозрачная расчётная логика на тестовом каталоге. Опасные работы требуют проверки специалиста.</p>`)}
<div class="top-gap">${card(`<div class="layout-spread"><strong class="small">Поделиться сценарием</strong>💡</div><p class="lead top-gap">Попробуйте изменить бюджет или включить сомнительный материал. Результат пересчитается по правилам проекта.</p>`)}</div></div></div>`;}
function renderPlan(p){return `<div class="top-gap">${card(`<div class="layout-spread"><div><div class="eyebrow">ВАШ РАСЧЁТ</div><h2 style="margin-top:6px">${p.emoji} ${enc(p.title)}</h2></div>${chip('Демо-смета','warn')}</div><div class="grid cols-3 top-gap">${[['Материалы',p.materials],['Экономия ZeroBuy',p.saved],['Стоимость варианта',p.estimated]].map(([l,v])=>`<div class="subtle-box"><small class="muted">${l}</small><div class="money-sm top-gap ${l.includes('Экономия')?'green-text':''}">${formatSum(v)}</div></div>`).join('')}</div>${sep()}<h3 class="bottom-gap">Выберите способ выполнения</h3>${p.options.map(o=>`<label class="option-card ${o.id===p.mode?'selected':''}"><div><div><input type="radio" name="result-mode" value="${o.id}" ${o.id===p.mode?'checked':''}><strong>${enc(o.title)}</strong></div><small>${enc(o.note)}</small></div><strong>${formatSum(o.total)}</strong></label>`).join('')}${p.estimated>p.budget?`<div class="warning critical">⚠️ Превышение бюджета на ${formatSum(p.estimated-p.budget)}. Выберите другой вариант или скорректируйте задачу.</div>`:`<div class="warning success">✅ Расчётный вариант укладывается в ваш бюджет. Остаток ${formatSum(p.budget-p.estimated)}.</div>`}${sep()}<h3 class="bottom-gap">Что купить в ОМА</h3>${p.items.map(item=>`<div class="list-row"><div class="item-emoji">${item.emoji}</div><div class="main-info"><strong>${enc(item.name)}</strong><small>Нужно ${item.needed} ${enc(item.unit)} · дома ${item.owned} · купить ${item.purchase} ${enc(item.unit)}</small></div><div class="text-right"><div class="price">${formatSum(item.subtotal)}</div>${item.owned?chip('ZeroBuy −'+formatSum(item.owned*item.price),'ok'):''}${!item.available?chip('Мало на складе','red'):''}</div></div>`).join('')}${sep()}<h3 class="bottom-gap">План выполнения</h3><div class="timeline">${p.steps.map((step,i)=>`<div class="timeline-step"><span class="timeline-num">${i+1}</span><div><strong>${enc(step.title)}</strong><small>Этап ${i+1}</small></div></div>`).join('')}</div>${sep()}<h3 class="bottom-gap">AntiFail: результаты проверки</h3>${p.warnings.map(w=>`<div class="warning ${w.level}"><span>${w.level==='critical'?'⛔':'ℹ️'}</span><div><strong>${enc(w.title)}</strong><div>${enc(w.detail)}</div></div></div>`).join('')}<div class="form-actions">${action('save-plan','💾 Сохранить проект','','data-busy')}${action('add-plan-cart','🛒 Добавить товары','secondary','data-busy')}${action('go-domino','🧩 Проверить порядок','outline')}</div><p class="tiny muted top-gap">${enc(p.disclaimer)}</p>`)}</div>`;}
function pageCatalog(){const data=S.data;const cats=['Все',...new Set(data.products.map(p=>p.category))];const items=data.products.filter(p=>(S.catalogCategory==='Все'||p.category===S.catalogCategory)&&(`${p.name} ${p.description}`.toLowerCase().includes(S.catalogQuery.toLowerCase())));return `${title('Каталог решений','Рабочий демонстрационный каталог: 28 товаров, цены и остатки по городам.',chip('Демо-каталог','warn'))}
<div class="card bottom-gap"><form id="catalog-form" class="small-form"><input class="input" type="search" id="catalog-search" placeholder="Найти товар по названию или описанию" value="${enc(S.catalogQuery)}" style="min-width:220px"><button class="btn" type="submit">Найти</button></form><div class="chips top-gap">${cats.map(cat=>`<button class="chip ${S.catalogCategory===cat?'active':''}" data-action="catalog-filter" data-id="${enc(cat)}">${enc(cat)}</button>`).join('')}</div></div><div class="layout-spread bottom-gap"><span class="small muted">Найдено: ${items.length}</span><span class="small muted">📍 ${enc(data.user.city)} · реальные цены и остатки не подключены</span></div>
${items.length?`<div class="product-grid">${items.map(p=>`<div class="product-card"><div class="product-visual"><span aria-hidden="true">${p.emoji}</span></div><div class="product-info"><span class="pill grey" style="align-self:flex-start">${enc(p.category)}</span><h3>${enc(p.name)}</h3><p class="two-line">${enc(p.description)}</p><div class="stock ${p.stock[data.user.city]?'':'no'}">● ${p.stock[data.user.city]?'Доступно: '+p.stock[data.user.city]+' '+enc(p.unit):'Нет в демо-остатках'}</div><div class="bottom"><span class="price">${money(p.price)} BYN<small class="muted">/${enc(p.unit)}</small></span><button class="btn sm" data-action="add-cart" data-id="${p.id}" ${p.stock[data.user.city]?'':'disabled'}>+ В корзину</button></div></div></div>`).join('')}</div>`:card(empty('⌕','Ничего не найдено','Измените запрос или выберите другую категорию.'))}`;}
function pageCart(){const d=S.data,items=d.cart,reservation=d.activeReservation,sum=items.reduce((s,item)=>s+item.quantity*item.product.price,0);return `${title('Корзина','Перед оформлением сервер резервирует остатки на 10 минут и ещё раз проверяет цену.',chip(`${items.length} позиций`))}
${items.length?`<div class="workarea"><div>${card(`<h3 class="bottom-gap">Ваш заказ</h3>${items.map(i=>`<div class="list-row"><div class="item-emoji">${i.product.emoji}</div><div class="main-info"><strong>${enc(i.product.name)}</strong><small>${i.quantity} ${enc(i.product.unit)} × ${formatSum(i.product.price)}</small><small class="stock ${i.product.stock[d.user.city]<i.quantity?'no':''}">${i.product.stock[d.user.city]<i.quantity?'Недостаточно остатков':'Есть в демонстрационном наличии'}</small></div><div class="text-right"><div class="price">${formatSum(i.product.price*i.quantity)}</div><button class="btn sm danger" data-action="remove-cart" data-id="${i.id}">Удалить</button></div></div>`).join('')}`)}</div><div class="sticky">${card(`<div class="eyebrow">ИТОГО</div><div class="money" style="margin:12px 0">${formatSum(sum)}</div>${badgeLine('Город',enc(d.user.city))}${badgeLine('Количество единиц',items.reduce((n,x)=>n+x.quantity,0))}${reservation?`<div class="warning success top-gap">✓ Остатки зарезервированы до ${new Date(reservation.expiresAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</div>`:''}${sep()}<p class="notice">Это тестовое оформление. Деньги не списываются, доставка не создаётся, ОМА не получает заказ.</p><button class="btn full top-gap" data-action="checkout" data-busy>Проверить остатки и оформить →</button>`)}<div class="top-gap">${action('open-catalog','← Продолжить покупки','outline')}</div></div></div>`:empty('🛒','Корзина пока пустая','Соберите умное решение или выберите товары в каталоге.',action('open-catalog','Открыть каталог'))}
<div class="section-title"><h2>История демо-заказов</h2></div>${d.orders.length?card(d.orders.map(o=>`<div class="list-row"><div class="item-emoji">📦</div><div class="main-info"><strong>Заказ ${enc(o.id)}</strong><small>${dt(o.createdAt)} · ${o.items.length} позиций · ${enc(o.status)}</small></div><strong class="price">${formatSum(o.total)}</strong></div>`).join('')):card('<p class="lead">Пока нет оформленных демо-заказов.</p>')}`;}
function projectSummary(p){return `<div class="list-row"><div class="item-emoji">${S.data.scenarios.find(s=>s.id===p.scenarioId)?.emoji||'📋'}</div><div class="main-info"><strong>${enc(p.title)}</strong><small>${dt(p.createdAt)} · ${enc(p.room||'Дом')} · бюджет ${formatSum(p.budget||0)}</small></div>${chip(p.status==='completed'?'Завершено':'В работе',p.status==='completed'?'ok':'warn')}<button class="btn sm secondary" data-action="open-project" data-id="${p.id}">Открыть</button></div>`;}
function pageProjects(){const d=S.data;const p=d.projects.find(p=>p.id===S.selectedProject);return `${title('Мои проекты','История задач, смет и подтверждённых пользователем результатов.',action('new-task','+ Новый проект'))}${d.projects.length?card(`<div class="eyebrow bottom-gap">ПРОЕКТЫ (${d.projects.length})</div>${d.projects.map(projectSummary).join('')}`):card(empty('📋','Проектов ещё нет','Сначала рассчитайте задачу, затем сохраните результат.',action('new-task','Создать проект')))}
${p?`<div class="section-title"><h2>Открыт проект</h2>${action('close-project','Закрыть','outline')}</div>${card(`<div class="layout-spread"><h2>${enc(p.title)}</h2>${chip(p.status==='completed'?'Завершён':'Запланирован',p.status==='completed'?'ok':'warn')}</div><div class="grid cols-3 top-gap">${[['Бюджет',formatSum(p.budget)],['Смета',formatSum(p.estimated)],['Этапы',String(p.plan?.steps?.length||0)]].map(([l,v])=>`<div class="subtle-box"><small class="muted">${l}</small><h3 class="top-gap">${v}</h3></div>`).join('')}</div>${p.plan?`<div class="section-title"><h3>Материалы</h3></div>${p.plan.items.map(i=>`<div class="list-row"><span class="item-emoji">${i.emoji}</span><div class="main-info"><strong>${enc(i.name)}</strong><small>Купить ${i.purchase} ${enc(i.unit)}</small></div><span class="price">${formatSum(i.subtotal)}</span></div>`).join('')}`:''}${p.proof?`<div class="banner top-gap"><div class="banner-emoji">✅</div><div><strong>Отмечено выполненным</strong><p>${enc(p.proof.note||'Без комментария')} · ${dt(p.proof.date)}. Самостоятельная отметка, не внешняя экспертиза.</p>${p.proof.object?`<img class="photo-proof" src="/api/v1/projects/${encodeURIComponent(p.id)}/proof-image" alt="Фото результата пользователя" loading="lazy">`:p.proof.image?`<img class="photo-proof" src="${p.proof.image}" alt="Фото результата пользователя" loading="lazy">`:''}</div></div>`:action('open-proof','✅ Подтвердить результат','secondary','style="margin-top:18px"')}`)}`:''}`;}
function pageZeroBuy(){const d=S.data,u=d.user,inventory=u.inventory||[];const value=inventory.reduce((a,i)=>a+(getProduct(i.productId)?.price||0)*i.qty,0);return `${title('ZeroBuy','Антикорзина: не покупайте то, что уже есть у вас дома.',chip('Реальный учёт запасов'))}
<div class="banner bottom-gap"><div class="banner-emoji">♻️</div><div><strong>Помним, что у вас уже есть</strong><p>Система исключает подходящие домашние материалы из расчёта покупки. Экономия считается по демонстрационным ценам.</p></div></div>
<div class="grid cols-3 bottom-gap">${[['Предметов',String(inventory.length)],['Оценка запасов',formatSum(value)],['Уже учтено в планах',S.plan?formatSum(S.plan.saved):'—']].map(([l,v])=>card(`<div class="kpi-label">${l}</div><div class="kpi-val">${v}</div>`,'kpi-card')).join('')}</div>
<div class="workarea"><div>${card(`<h3 class="bottom-gap">Мои материалы и инструменты</h3>${inventory.length?inventory.map(item=>`<div class="list-row"><span class="item-emoji">${getProduct(item.productId)?.emoji||'📦'}</span><div class="main-info"><strong>${enc(item.name)}</strong><small>${item.qty} шт. дома</small></div><button class="btn sm danger" data-action="remove-inventory" data-id="${item.id}">Удалить</button></div>`).join(''):empty('📦','Пока пусто','Добавьте материалы или инструменты, которые у вас уже есть.')}`)}</div>
<div class="sticky">${card(`<div class="eyebrow bottom-gap">ДОБАВИТЬ В ЗАПАСЫ</div><form id="inventory-form"><div class="form-group"><label>Товар из каталога</label><select class="select" id="inv-product" required>${d.products.map(p=>`<option value="${p.id}">${enc(p.name)} · ${formatSum(p.price)}</option>`).join('')}</select></div><div class="form-group top-gap"><label>Количество</label><input class="input" id="inv-qty" type="number" min="1" max="1000" value="1" required></div><button type="submit" class="btn full top-gap" data-busy>+ Добавить в мой дом</button></form>${sep()}<p class="lead">После добавления заново рассчитайте задачу — ZeroBuy автоматически вычтет уже имеющееся.</p>${action('new-task','Рассчитать с учётом запасов','secondary','style="margin-top:15px"')}`)}</div></div>`;}
function pageAntiFail(){const p=S.plan;return `${title('AntiFail','Проверяем материалы, остатки и критичные ограничения до заказа.',chip('Объяснимая проверка'))}${p?`
<div class="grid cols-3 bottom-gap">${[['Проверок',p.warnings.length],['Критических',p.warnings.filter(x=>x.level==='critical').length],['Не хватает остатков',p.items.filter(x=>!x.available).length]].map(([l,v])=>card(`<div class="kpi-label">${l}</div><div class="kpi-val">${v}</div>`,'kpi-card')).join('')}</div>
<div class="workarea"><div>${card(`<h3 class="bottom-gap">Результаты для «${enc(p.title)}»</h3>${p.warnings.map(w=>`<div class="warning ${w.level}" style="margin-bottom:9px">${w.level==='critical'?'⛔':'🔎'} <div><strong>${enc(w.title)}</strong><p>${enc(w.detail)}</p></div></div>`).join('')}${sep()}<h3>Наличие по вашему городу: ${enc(p.city)}</h3>${p.items.map(i=>`<div class="list-row"><div class="item-emoji">${i.emoji}</div><div class="main-info"><strong>${enc(i.name)}</strong><small>Нужно купить: ${i.purchase}</small></div>${chip(i.available?'В демо-наличии':'Недостаточно',i.available?'ok':'red')}</div>`).join('')}`)}</div><div class="sticky">${card(`<h3>Проверить риск</h3><p class="lead top-gap bottom-gap">Смоделируйте ошибку выбора материала и посмотрите, как система её объяснит.</p>${action('toggle-risk',p.flagged?'Снять отметку риска':'⚠️ Проверить сомнительный материал',p.flagged?'secondary':'')}${sep()}<p class="notice">AntiFail не является инженерной экспертизой. Технические рекомендации требуют проверки документации и специалиста.</p>`)}</div></div>`:card(empty('🛡️','Сначала создайте расчёт','AntiFail проверит ваш проект после запуска планировщика.',action('new-task','Создать расчёт')))}
`;}
function pageDomino(){const p=S.plan;const conflicts=S.sequenceConflicts||[];return `${title('Domino','Правильный порядок работ экономит деньги и помогает избежать переделок.',chip('Граф зависимостей'))}${p?`<div class="workarea"><div>${card(`<div class="layout-spread bottom-gap"><h3>${enc(p.title)}</h3>${chip('Переставляйте шаги')}</div><p class="lead bottom-gap">Измените порядок этапов стрелками и нажмите «Проверить порядок».</p>${p.steps.map((step,i)=>`<div class="list-row"><div class="timeline-num">${i+1}</div><div class="main-info"><strong>${enc(step.title)}</strong><small>Зависимости: ${(step.after||[]).map(k=>enc(p.steps.find(x=>x.id===k)?.title||k)).join(' · ')||'нет'}</small></div><button class="btn sm outline" data-action="step-up" data-index="${i}" aria-label="Переместить «${enc(step.title)}» выше" ${i===0?'disabled':''}>↑</button><button class="btn sm outline" data-action="step-down" data-index="${i}" aria-label="Переместить «${enc(step.title)}» ниже" ${i===p.steps.length-1?'disabled':''}>↓</button></div>`).join('')}<div class="form-actions">${action('validate-sequence','🧩 Проверить порядок')}${action('reset-sequence','Вернуть правильный порядок','outline')}</div>${S.sequenceConflicts!==null?`<div class="top-gap">${conflicts.length?conflicts.map(c=>`<div class="warning critical">⛔ «${enc(c.step)}» должен идти после «${enc(c.after)}»</div>`).join(''):`<div class="warning success">✅ Конфликтов зависимостей в демонстрационном графе не обнаружено.</div>`}</div>`:''}`)}</div><div class="sticky">${card(`<div class="banner"><div class="banner-emoji">🧩</div><div><strong>Домино-эффект</strong><p>Если перенести отделку перед инженерными работами, может понадобиться повторный демонтаж.</p></div></div>${sep()}<p class="lead">В демо используются заданные экспертные зависимости. Реальный граф работ зависит от объекта, технологии и согласований.</p>`)}</div></div>`:card(empty('🧩','Создайте проект','Сначала выберите задачу, а потом экспериментируйте с порядком этапов.',action('new-task','Создать проект')))}
`;}
function pageSyncCity(){const d=S.data,u=d.user;const filtered=d.groups.filter(g=>g.city===u.city);return `${title('SyncCity','Соседи объединяют логистику, выезды мастеров и закупки. Без публикации точных адресов.',chip('Групповые заказы'))}
<div class="banner bottom-gap"><div class="banner-emoji">🏘️</div><div><strong>Один маршрут. Несколько полезных задач.</strong><p>Групповые скидки здесь модельные: реальные условия может подтвердить только партнёр или ОМА.</p></div></div><div class="workarea"><div><div class="grid cols-2">${filtered.map(g=>{const joined=g.memberIds.includes(u.id),percent=Math.min(100,g.participants/g.target*100),saving=Math.round(g.basePrice*(g.participants>=g.target?.18:g.participants>=Math.ceil(g.target/2)?.1:0));return `<div class="card hover"><div class="layout-spread bottom-gap">${chip(g.category)}${chip(g.district===u.district?'Ваш район':'Ваш город',g.district===u.district?'ok':'grey')}</div><h3>${enc(g.title)}</h3><p class="lead top-gap">${enc(g.description)}</p><div class="layout-spread top-gap"><strong class="small">${g.participants} / ${g.target} участников</strong><span class="small green-text">Возможная выгода ${formatSum(saving)}</span></div><div class="meter top-gap"><i style="width:${percent}%"></i></div><div class="layout-spread top-gap"><small class="muted">${enc(g.district)} · ${enc(g.date)}</small><button class="btn sm ${joined?'secondary':''}" data-action="join-group" data-id="${g.id}" ${joined?'disabled':''}>${joined?'Вы участвуете':'Присоединиться'}</button></div></div>`;}).join('')||card(empty('📍','Групп пока нет','Создайте первую групповую заявку в вашем городе.'))}</div></div><div class="sticky">${card(`<div class="eyebrow bottom-gap">НОВАЯ ГРУППА</div><form id="group-form"><div class="form-group"><label>Название задачи</label><input class="input" id="group-title" maxlength="100" required placeholder="Совместная доставка плитки"></div><div class="form-group top-gap"><label>Категория</label><select class="select" id="group-category"><option>Доставка</option><option>Сантехника</option><option>Ремонт</option><option>Сад</option><option>Другое</option></select></div><div class="form-grid top-gap"><div class="form-group"><label>Цель, семей</label><input class="input" id="group-target" type="number" min="2" max="100" value="6"></div><div class="form-group"><label>Условная цена, BYN</label><input class="input" id="group-price" type="number" min="0" value="100"></div></div><button type="submit" class="btn full top-gap" data-busy>+ Создать группу</button></form>${sep()}<p class="notice">В демонстрационной версии нет реального бронирования мастеров и расчёта транспортных тарифов.</p>`)}</div></div>`;}
function pageProof(){const d=S.data,active=d.projects.filter(p=>p.status!=='completed'),completed=d.projects.filter(p=>p.status==='completed'),selected=active.find(x=>x.id===S.selectedProject)||active[0];return `${title('Proof','История выполненных работ. Фотографии и чеки не заменяют независимую техническую приёмку.',chip('Цифровой паспорт'))}
<div class="grid cols-3 bottom-gap">${[['Всего проектов',d.projects.length],['Завершено',completed.length],['Ожидают приёмки',active.length]].map(([l,v])=>card(`<div class="kpi-label">${l}</div><div class="kpi-val">${v}</div>`,'kpi-card')).join('')}</div>
<div class="workarea"><div>${card(`<h3 class="bottom-gap">История жилья</h3>${d.projects.length?d.projects.map(p=>`<div class="list-row"><div class="item-emoji">${p.status==='completed'?'✅':'📝'}</div><div class="main-info"><strong>${enc(p.title)}</strong><small>${dt(p.createdAt)} · ${p.status==='completed'?'Выполнено, подтверждено владельцем':'Ожидает отметки'}</small></div>${p.status!=='completed'?`<button class="btn sm secondary" data-action="proof-select" data-id="${p.id}">Завершить</button>`:chip('В паспорте','ok')}</div>`).join(''):empty('🏡','История пуста','Создайте и сохраните проект в планировщике.')}`)}</div><div class="sticky">${card(`<div class="eyebrow bottom-gap">ПРИЁМКА РЕЗУЛЬТАТА</div>${selected?`<h3>${enc(selected.title)}</h3><form id="proof-form" class="top-gap"><input type="hidden" id="proof-project" value="${selected.id}"><div class="checklist"><label><input type="checkbox" name="proof-check" required> Работа выполнена по согласованному плану</label><label><input type="checkbox" name="proof-check" required> Результат осмотрен, замечания записаны</label><label><input type="checkbox" name="proof-check" required> Документы и инструкции сохранены</label></div><div class="form-group top-gap"><label>Комментарий владельца</label><textarea class="textarea" id="proof-note" maxlength="900" placeholder="Что было сделано и какие замечания остались?"></textarea></div><div class="form-group top-gap"><label>Фотография результата (необязательно, до 1 МБ)</label><input class="input" type="file" id="proof-image" accept="image/png,image/jpeg,image/webp" style="padding:9px"></div><button class="btn full top-gap" type="submit" data-busy>✅ Сохранить в историю дома</button></form>`:empty('🎉','Все проекты завершены','Создайте новую задачу, чтобы сохранить результат.')}${sep()}<p class="notice">Статус Proof означает самостоятельную отметку владельца. Без экспертизы мы не присваиваем статус «подтверждено специалистом».</p>`)}</div></div>`;}
function pageDna(){const d=S.data;return `${title('OMA DNA','Не начинайте с нуля: адаптируйте проверенные примеры под свой объект.',chip('Библиотека решений'))}
<div class="banner bottom-gap"><div class="banner-emoji">🧬</div><div><strong>Опыт одного дома помогает другим</strong><p>Сходство оценивается по типу здания, помещению и площади. Все примеры и количество повторений — демонстрационные данные.</p></div></div><div class="grid cols-3">${d.templates.map(t=>`<div class="card hover"><div class="layout-spread">${chip(t.room)}${chip(`${t.match}% совпадение`,'ok')}</div><div style="font-size:48px;margin:16px 0">${d.scenarios.find(s=>s.id===t.scenarioId)?.emoji||'🏡'}</div><h3>${enc(t.name)}</h3><p class="lead top-gap" style="min-height:55px">${enc(t.description)}</p><div class="layout-spread top-gap"><small class="muted">Площадь ${t.area} м²</small><small class="muted">${t.uses} повторений*</small></div>${sep()}<div class="layout-spread"><div><div class="eyebrow" style="font-size:9px">Базовая смета*</div><strong>${formatSum(t.cost)}</strong></div><button class="btn sm" data-action="dna-use" data-id="${t.id}" data-busy>Адаптировать →</button></div></div>`).join('')}</div><p class="tiny muted top-gap">*Вымышленные проекты, повторения и сметы. В реальной версии нужна проверка и разрешение на использование данных владельцев.</p>`;}
function pageForge(){const d=S.data;return `${title('OMA FORGE','Новые комплекты формируются из повторяющихся реальных потребностей.',chip('Клиентский спрос'))}
<div class="banner bottom-gap"><div class="banner-emoji">⚙️</div><div><strong>Покупатели помогают создавать ассортимент</strong><p>Голосуйте за комплекты. Менеджер решает, стоит ли выпускать решение. Всё в демо, без реальных предзаказов.</p></div></div><div class="grid cols-3">${d.forge.map(f=>{const voted=f.voters.includes(d.user.id),percent=Math.min(100,100*f.interested/f.threshold);return `<div class="card hover"><div class="layout-spread">${chip(f.category)}${chip(f.approved?'Утверждено в демо':'Проверка спроса',f.approved?'ok':'grey')}</div><div style="font-size:52px;margin:17px 0">${f.emoji}</div><h3>${enc(f.name)}</h3><p class="lead top-gap" style="min-height:55px">${enc(f.description)}</p><div class="layout-spread top-gap"><strong class="small">${f.interested} / ${f.threshold} заинтересованы</strong><small class="green-text">${f.interested>=f.threshold?'Достигнут порог':'Сбор спроса'}</small></div><div class="meter top-gap"><i style="width:${percent}%"></i></div>${sep()}<div class="layout-spread"><div><span class="tiny muted">Модельная цена</span><div class="money-sm">${formatSum(f.priceNow)}</div></div><button class="btn sm ${voted?'secondary':''}" data-action="vote-forge" data-id="${f.id}" ${voted?'disabled':''}>${voted?'Ваш голос учтён':'+ Хочу комплект'}</button></div></div>`;}).join('')}</div>
${d.permissions?.canManageForge?`<div class="section-title"><h2>Панель менеджера · демо</h2></div>${card(`<p class="lead bottom-gap">Демонстрация будущего процесса согласования товарных комплектов. Нажатия не меняют ассортимент ОМА.</p>${d.forge.map(f=>`<div class="list-row"><span class="item-emoji">${f.emoji}</span><div class="main-info"><strong>${enc(f.name)}</strong><small>Интерес: ${f.interested} · целевой порог: ${f.threshold}</small></div><button class="btn sm outline" data-action="approve-forge" data-id="${f.id}">${f.approved?'Отозвать демо-решение':'Демо: утвердить'}</button></div>`).join('')}`)}`:`<div class="section-title"><h2>Согласование комплектов</h2></div>${card('<p class="lead">Решения о выпуске доступны только менеджерам. Ваш голос учитывается как сигнал спроса.</p>')}`}`;}
function pagePulse(){const d=S.data;return `${title('OMA PULSE','Коллективные сигналы о повторяющихся проблемах — не диагноз и не предсказание поломки.',chip('Ранняя осведомлённость'))}
<div class="banner bottom-gap"><div class="banner-emoji">💓</div><div><strong>Узнавайте о похожих проблемах раньше</strong><p>Система ищет повторения в обезличенных подтверждённых случаях и показывает осторожные рекомендации по проверке.</p></div></div>
<div class="workarea"><div>${d.pulse.map(p=>card(`<div class="layout-spread bottom-gap"><div>${chip('Демо-сигнал',p.level==='attention'?'warn':'grey')} ${chip(p.category)}</div>${chip(p.verifiedCases+' подтверждённых кейсов*')}</div><h3>${enc(p.name)}</h3><p class="lead top-gap"><strong>Критерий:</strong> ${enc(p.match)}</p><div class="subtle-box top-gap"><div class="eyebrow">КАК ДЕЙСТВОВАТЬ</div><p class="lead top-gap">${enc(p.recommendation)}</p></div><div class="layout-spread top-gap"><span class="tiny muted">Модель: ${enc(p.model)}</span><button class="btn sm ${d.user.pulseSubscriptions.includes(p.id)?'secondary':''}" data-action="pulse-sub" data-id="${p.id}">${d.user.pulseSubscriptions.includes(p.id)?'✓ Подписаны':'Следить за сигналом'}</button></div>`,'bottom-gap')).join('')}<p class="tiny muted">*Все кейсы демонстрационные, без реальных жалоб клиентов ОМА. Личные адреса и данные других жителей не раскрываются.</p></div>
<div class="sticky">${card(`<div class="eyebrow bottom-gap">СООБЩИТЬ О ПРОБЛЕМЕ</div><form id="pulse-form"><div class="form-group"><label>Категория</label><select class="select" id="pulse-category"><option>Сантехника</option><option>Крепёж</option><option>Отделка</option><option>Бытовая техника</option><option>Другое</option></select></div><div class="form-group top-gap"><label>Модель/маркировка (если известна)</label><input class="input" id="pulse-model" placeholder="Например: серия A35" maxlength="80"></div><div class="form-group top-gap"><label>Что произошло?</label><textarea class="textarea" id="pulse-symptom" required minlength="8" maxlength="450" placeholder="Опишите проблему без персональных данных"></textarea></div><button class="btn full top-gap" type="submit" data-busy>Отправить на проверку</button></form>${sep()}<p class="notice">Новое сообщение не считается подтверждённым дефектом и не формирует автоматическое массовое предупреждение.</p>`)}${d.reports.length?card(`<h3>Мои сообщения</h3>${d.reports.map(r=>`<div class="list-row"><div class="main-info"><strong>${enc(r.model||r.category)}</strong><small>${enc(r.symptom)}</small></div>${chip(r.status,'warn')}</div>`).join('')}`,'top-gap'):''}</div></div>`;}
function pageBusiness(){const m=S.metrics||S.data.metrics;const eff=m.contribution;return `${title('Экономика проекта','Прозрачная модель маржинального вклада одного заказа. Настраиваемые гипотезы, не финансовые показатели ОМА.',chip('Сценарная модель'))}
<div class="grid cols-4 bottom-gap">${[['Заказов (демо)',S.data.metrics.orders],['Проектов (демо)',S.data.metrics.projects],['Модулей',8],['Вклад / заказ',formatSum(eff)]].map(([l,v])=>card(`<div class="kpi-label">${l}</div><div class="kpi-val">${v}</div>`,'kpi-card')).join('')}</div><div class="workarea"><div>${card(`<h3 class="bottom-gap">Сценарий выручки и затрат</h3><form id="metrics-form"><div class="form-grid">${[['aov','Средний товарный чек, BYN',m.aov],['margin','Валовая маржа товаров, %',Math.round(m.margin*100)],['avgService','Средняя стоимость услуг, BYN',m.avgService],['commission','Комиссия за услугу, %',Math.round(m.commission*100)],['cost','Переменные расходы на заказ, BYN',m.cost]].map(([key,label,value])=>`<div class="form-group"><label>${label}</label><input class="input" id="m-${key}" type="number" step="1" min="0" value="${value}"></div>`).join('')}</div><button class="btn top-gap" type="submit">Пересчитать экономику</button></form>${sep()}<div class="subtle-box"><div class="eyebrow">МАРЖИНАЛЬНЫЙ ВКЛАД (ГИПОТЕЗА)</div><div class="money top-gap ${eff>=0?'green-text':'red-text'}">${formatSum(eff)}</div><div class="tiny muted top-gap">Товарная валовая прибыль + комиссия за услуги − переменные расходы.</div></div><p class="lead top-gap">Модель не включает постоянные затраты, налоги, возвраты и стоимость интеграции. Для бизнес-плана понадобятся реальные данные ОМА.</p>`)}</div><div class="sticky">${card(`<h3>Как ОМА зарабатывает</h3><div class="timeline top-gap">${[['01','Дополнительные товарные корзины'],['02','Комиссия от услуг партнёров'],['03','Больше повторных задач'],['04','OMA FORGE: новые комплекты'],['05','SyncCity: оптимизация логистики']].map(([n,s])=>`<div class="timeline-step"><span class="timeline-num">${n}</span><strong class="small">${s}</strong></div>`).join('')}</div>${sep()}<div class="warning info">ℹ️ Поездка в магазин, мастер или новый комплект не гарантируют прибыль. Экономика требует проверки спроса, договоров и затрат.</div>`)}</div></div>`;}
function pageProfile(){const d=S.data,u=d.user;return `${title('Мой дом','Один профиль жилья связывает все восемь сервисов и сохраняет историю задач.',chip('Демо-профиль'))}
<div class="workarea"><div>${card(`<div class="eyebrow bottom-gap">ПАРАМЕТРЫ ЖИЛЬЯ</div><form id="profile-form"><div class="form-grid"><div class="form-group"><label>Как к вам обращаться</label><input class="input" id="u-name" value="${enc(u.name)}" maxlength="60" required></div><div class="form-group"><label>Город</label><select class="select" id="u-city">${d.cities.map(c=>`<option ${u.city===c?'selected':''}>${enc(c)}</option>`).join('')}</select></div><div class="form-group"><label>Тип объекта</label><select class="select" id="u-kind">${['Квартира','Частный дом','Дача','Другое'].map(c=>`<option ${u.kind===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-group"><label>Тип здания</label><select class="select" id="u-type">${['Панельный дом','Монолитный дом','Кирпичный дом','Частный дом'].map(c=>`<option ${u.homeType===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-group"><label>Площадь, м²</label><input class="input" id="u-area" type="number" min="1" max="10000" value="${u.area}"></div><div class="form-group"><label>Количество комнат</label><input class="input" id="u-rooms" type="number" min="1" max="20" value="${u.rooms}"></div><div class="form-group"><label>Район (для групповых заказов)</label><input class="input" id="u-district" maxlength="100" value="${enc(u.district)}" placeholder="Например: Фрунзенский"></div></div><div class="section-title"><h3>Примерные площади помещений</h3></div><div class="form-grid">${['Прихожая','Ванная','Комната','Балкон','Кухня','Сад'].map((r,i)=>`<div class="form-group"><label>${r}, м²</label><input class="input" id="room-${i}" type="number" min="0" max="1000" step=".1" value="${u.roomAreas?.[r]??0}"></div>`).join('')}</div><p class="tiny muted top-gap">Эти параметры используются при расчёте сходства OMA DNA.</p><button type="submit" class="btn top-gap" data-busy>Сохранить профиль</button></form>`)}
${card(`<h3>Прозрачность и безопасность</h3><p class="lead top-gap">Состояние пилота хранится в PostgreSQL. Профиль определяется защищённой серверной сессией, изменения требуют CSRF-токен, а административные действия проверяют роль.</p><p class="lead top-gap">Демо-вход предназначен только для пилота. Для production требуется корпоративный OIDC/SSO и утверждённые правила обработки персональных данных.</p>`,'top-gap')}</div>
<div class="sticky">${d.demo?card(`<div class="eyebrow bottom-gap">ДЕМОНСТРАЦИОННЫЕ ПРОФИЛИ</div><p class="lead bottom-gap">Переключайте пользователей, чтобы показать как SyncCity объединяет действия разных аккаунтов.</p>${d.users.map(x=>`<button class="option-card ${x.id===u.id?'selected':''}" style="width:100%" data-action="switch-user" data-id="${x.id}"><span class="row-wrap"><span class="avatar">${enc(x.name.slice(0,1))}</span><span><strong>${enc(x.name)}</strong><small>${enc(x.city)} · ${enc(x.kind)}</small></span></span>${x.id===u.id?'✓':'→'}</button>`).join('')}${sep()}<form id="new-user-form"><div class="form-group"><label>Создать новый демо-профиль</label><input class="input" id="new-user-name" placeholder="Имя" maxlength="60" required></div><button class="btn secondary full top-gap" type="submit">+ Добавить профиль</button></form>`):card(`<div class="eyebrow bottom-gap">АКТИВНАЯ СЕССИЯ</div><strong>${enc(u.name)}</strong><p class="lead top-gap">Роли: ${enc((d.roles||[]).join(', '))}</p>`)}
</div></div>`;}
function pageMore(){return `${title('Все сервисы','Дополнительные возможности собраны в одном месте, чтобы основная навигация оставалась простой.',chip('8 умных модулей'))}<div class="feature-grid">${FEATURE.map(([v,e,n,desc])=>`<button class="feature-card" data-view="${v}"><span class="feature-icon" aria-hidden="true">${e}</span><strong>${n} →</strong><span>${enc(desc)}</span></button>`).join('')}</div><div class="section-title"><h2>Профиль и управление</h2></div><div class="grid cols-3">${[['profile','👤','Мой дом','Параметры жилья и безопасность'],['cart','🛒','Корзина','Резервирование и история заказов'],['business','📊','Экономика','Проверка гипотез пилота']].map(([v,e,n,d])=>`<button class="feature-card" data-view="${v}"><span class="feature-icon" aria-hidden="true">${e}</span><strong>${n} →</strong><span>${d}</span></button>`).join('')}</div>`;}
async function solveTask(values){const result=await api('/solve','POST',{scenarioId:values.scenarioId||S.scenario,task:values.task||sc().title,budget:values.budget??sc().defaultBudget,area:values.area??sc().area,mode:values.mode||S.planMode,wrongMaterial:values.wrongMaterial||false});S.plan=result.plan;S.calculationId=result.calculationId;S.scenario=result.plan.scenarioId;S.planMode=result.plan.mode;S.sequenceConflicts=null;S.view='planner';window.history.replaceState({view:'planner'},'',viewUrl('planner'));track('calculation_completed',{view:'planner',scenarioId:S.scenario});render();return result.plan;}
async function handleAction(actionName,el){const id=el.dataset.id;
 switch(actionName){
 case 'new-task':track('task_started',{view:'home'});changeView('planner');break;
 case 'choose-scenario':case 'select-scenario':S.scenario=id;S.plan=null;S.calculationId=null;S.sequenceConflicts=null;S.planMode='hybrid';changeView('planner');break;
 case 'catalog-filter':S.catalogCategory=id;render();break;
 case 'add-cart':await mutation(()=>api('/cart/items','POST',{productId:id,quantity:1}),'Товар добавлен в корзину');break;
 case 'remove-cart':await mutation(()=>api('/cart/items/'+id,'DELETE',{}),'Товар убран');break;
 case 'checkout':await mutation(async()=>{const {reservation}=await api('/cart/reserve','POST',{});track('reservation_created',{view:'cart'});const result=await api('/orders','POST',{reservationId:reservation.id});track('order_created',{view:'cart'});return result;},'Демо-заказ создан. Оплата не производится.');break;
 case 'save-plan':if(!S.plan||!S.calculationId)return;await mutation(async()=>{const res=await api('/projects','POST',{calculationId:S.calculationId});S.selectedProject=res.project.id;track('project_saved',{view:'planner',scenarioId:S.scenario});return res;},'Проект сохранён в профиле жилья');break;
 case 'add-plan-cart':if(!S.plan||!S.calculationId)return;await mutation(async()=>{await api('/cart/import-plan','POST',{calculationId:S.calculationId});track('cart_imported',{view:'planner',scenarioId:S.scenario});S.view='cart';},'Все необходимые товары добавлены в корзину');break;
 case 'go-domino':changeView('domino');break;
 case 'open-catalog':changeView('catalog');break;
 case 'open-dna':changeView('dna');break;
 case 'open-project':S.selectedProject=id;changeView('projects');break;
 case 'close-project':S.selectedProject=null;render();break;
 case 'open-proof':changeView('proof');break;
 case 'proof-select':S.selectedProject=id;changeView('proof');break;
 case 'remove-inventory':await mutation(()=>api('/inventory/'+id,'DELETE',{}),'Запас удалён');break;
 case 'toggle-risk':if(!S.plan)return;await mutation(async()=>{await solveTask({...S.plan,wrongMaterial:!S.plan.flagged});S.view='antifail';},'Проверка обновлена');break;
 case 'step-up':case 'step-down':if(!S.plan)return;{const n=Number(el.dataset.index),j=actionName==='step-up'?n-1:n+1;if(j>=0&&j<S.plan.steps.length){const steps=S.plan.steps;[steps[n],steps[j]]=[steps[j],steps[n]];S.sequenceConflicts=null;render();}}break;
 case 'validate-sequence':if(!S.plan||!S.calculationId)return;{const res=await api('/sequence/validate','POST',{calculationId:S.calculationId,stepIds:S.plan.steps.map(step=>step.id)});S.sequenceConflicts=res.conflicts;render();notify(res.conflicts.length?`Обнаружено конфликтов: ${res.conflicts.length}`:'Порядок проверен');}break;
 case 'reset-sequence':if(!S.plan)return;await mutation(()=>solveTask({task:S.plan.task,scenarioId:S.plan.scenarioId,budget:S.plan.budget,area:S.plan.area,mode:S.plan.mode,wrongMaterial:S.plan.flagged}),'Правильный порядок восстановлен');break;
 case 'join-group':await mutation(()=>api('/groups/'+id+'/join','POST',{}),'Вы добавлены в демонстрационную группу');break;
 case 'dna-use':{const t=S.data.templates.find(x=>x.id===id);if(!t)return;S.scenario=t.scenarioId;S.planMode='hybrid';await mutation(()=>solveTask({scenarioId:t.scenarioId,task:t.name,budget:Math.max(t.cost+300,100),area:t.area,mode:'hybrid'}),'Проект адаптирован. Проверьте состав и ограничения.');break;}
 case 'vote-forge':await mutation(()=>api('/forge/'+id+'/vote','POST',{}),'Ваш интерес к комплекту учтён');break;
 case 'approve-forge':await mutation(()=>api('/forge/'+id+'/approve','POST',{}),'Решение изменено только в демо');break;
 case 'pulse-sub':await mutation(()=>api('/pulse/'+id+'/subscribe','POST',{}),'Настройка наблюдения сохранена (внутри приложения)');break;
 case 'switch-user':{const result=await api('/auth/demo','POST',{userId:id});S.userId=result.user.id;S.plan=null;S.calculationId=null;S.selectedProject=null;S.metrics=null;localStorage.setItem('oma-demo-user',S.userId);await load();changeView('profile');notify('Активный профиль переключён');break;}
 case 'chat-toggle':S.chatOpen=!S.chatOpen;render();if(S.chatOpen)$('#chat-body')?.scrollTo(0,99999);break;
 case 'help':modalReturnFocus=document.activeElement;S.modal={title:'OMA ONE · production-пилот',text:'В пилоте работают расчёты, корзина, проекты и восемь сервисных модулей. Локальный каталог и операции остаются демонстрационными до подключения API ОМА.',body:`<div class="warning info">ℹ️ Демо-профили не требуют пароля. Не вводите конфиденциальные данные. В production используется OIDC/SSO.</div>`};render();break;
 case 'close-modal':S.modal=null;render();modalReturnFocus?.focus?.();modalReturnFocus=null;break;
 case 'reload':location.reload();break;
 default:console.warn('Unknown action',actionName);
 }
}
document.addEventListener('click',async event=>{if(event.target.matches('[data-modal-backdrop]')){await handleAction('close-modal',event.target);return;}const view=event.target.closest('[data-view]');if(view){event.preventDefault();changeView(view.dataset.view);return;}const a=event.target.closest('[data-action]');if(a){event.preventDefault();try{await handleAction(a.dataset.action,a);}catch(e){trackError(e,S.view);notify(e.message,true);console.error(e);}return;}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(S.modal){event.preventDefault();handleAction('close-modal',document.body);}else if(S.chatOpen){event.preventDefault();handleAction('chat-toggle',document.body);}return;}if(event.key==='Tab'&&S.modal){const focusable=[...document.querySelectorAll('.modal button,.modal a,.modal input,.modal select,.modal textarea')].filter(item=>!item.disabled);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.addEventListener('change',async event=>{if(event.target.name==='result-mode'&&S.plan){const mode=event.target.value;S.planMode=mode;try{await mutation(()=>solveTask({task:S.plan.task,scenarioId:S.plan.scenarioId,budget:S.plan.budget,area:S.plan.area,mode,wrongMaterial:S.plan.flagged}),'Вариант пересчитан на сервере');}catch(error){notify(error.message,true);}}});
async function fileToCompressedDataURL(file){if(!file)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Поддерживаются JPEG, PNG и WEBP');if(file.size>8_000_000)throw new Error('Исходное изображение слишком большое');return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);const scale=Math.min(1,900/Math.max(img.width,img.height));const can=document.createElement('canvas');can.width=Math.max(1,Math.round(img.width*scale));can.height=Math.max(1,Math.round(img.height*scale));can.getContext('2d').drawImage(img,0,0,can.width,can.height);const result=can.toDataURL('image/jpeg',.72);if(result.length>1_600_000)reject(new Error('Фото после сжатия слишком большое'));else resolve(result);};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Не удалось прочитать изображение'));};img.src=url;});}
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id)return;event.preventDefault();if(S.busy)return;
 try{
 switch(form.id){
 case 'chat-form':{const msg=$('#chat-message').value.trim();if(!msg)return;S.chatMessages.push({role:'user',text:msg});S.chatTyping=true;render();try{const response=await api('/assistant','POST',{message:msg,scenarioId:S.plan?.scenarioId||null});S.chatMessages.push({role:'assistant',text:response.answer});}catch(e){S.chatMessages.push({role:'assistant',text:'Не удалось получить ответ: '+e.message});}S.chatTyping=false;render();$('#chat-body')?.scrollTo(0,99999);break;}
 case 'plan-form':{S.planMode=$('#task-mode').value;await mutation(()=>solveTask({scenarioId:S.scenario,task:$('#task-text').value,budget:Number($('#task-budget').value),area:Number($('#task-area').value),mode:S.planMode,wrongMaterial:$('#task-risk').checked}),'Расчёт готов');break;}
 case 'catalog-form':S.catalogQuery=$('#catalog-search').value.trim();render();break;
 case 'inventory-form':await mutation(()=>api('/inventory','POST',{productId:$('#inv-product').value,qty:Number($('#inv-qty').value)}),'Домашний запас обновлён');break;
 case 'group-form':await mutation(()=>api('/groups','POST',{title:$('#group-title').value,category:$('#group-category').value,target:Number($('#group-target').value),basePrice:Number($('#group-price').value)}),'Группа создана');break;
 case 'proof-form':{const image=await fileToCompressedDataURL($('#proof-image').files[0]);await mutation(async()=>{const result=await api('/projects/'+$('#proof-project').value+'/complete','POST',{checklist:[...form.querySelectorAll('input[name="proof-check"]')].map(x=>x.checked),note:$('#proof-note').value,image});track('proof_completed',{view:'proof'});return result;},'Результат сохранён в истории дома');break;}
 case 'pulse-form':await mutation(()=>api('/pulse/report','POST',{model:$('#pulse-model').value,category:$('#pulse-category').value,symptom:$('#pulse-symptom').value}),'Сообщение создано со статусом «Требует проверки»');break;
 case 'metrics-form':{S.metrics=await api('/metrics','POST',{aov:Number($('#m-aov').value),margin:Number($('#m-margin').value),avgService:Number($('#m-avgService').value),commission:Number($('#m-commission').value),cost:Number($('#m-cost').value)});render();notify('Экономика пересчитана');break;}
 case 'profile-form':await mutation(()=>api('/users/me','PATCH',{name:$('#u-name').value,city:$('#u-city').value,kind:$('#u-kind').value,homeType:$('#u-type').value,area:Number($('#u-area').value),rooms:Number($('#u-rooms').value),district:$('#u-district').value,roomAreas:Object.fromEntries(['Прихожая','Ванная','Комната','Балкон','Кухня','Сад'].map((r,i)=>[r,Number($('#room-'+i).value)]))}),'Профиль обновлён');break;
 case 'new-user-form':await mutation(async()=>{const r=await api('/users','POST',{name:$('#new-user-name').value,city:S.data.user.city});S.userId=r.user.id;localStorage.setItem('oma-demo-user',S.userId);S.plan=null;S.calculationId=null;S.selectedProject=null;S.metrics=null;},'Новый демо-профиль готов');break;
 }
 }catch(e){trackError(e,S.view);notify(e.message,true);console.error(e);}
});
function renderFatal(error){const offline=!navigator.onLine;$('#app').innerHTML=`<main class="fatal-state"><div class="pre-icon" aria-hidden="true">${offline?'◌':'⚠️'}</div><h1>${offline?'Нет подключения':'Не удалось запустить приложение'}</h1><p>${offline?'Подключитесь к сети и повторите попытку.':enc(error.message)}</p><button class="btn" data-action="reload">Попробовать снова</button></main>`;}
function updateConnectivity(){const online=navigator.onLine;if(S.online===online)return;S.online=online;track('offline_changed',{online});if(S.data)render();notify(online?'Подключение восстановлено':'Вы офлайн. Изменения временно недоступны.',!online);}
window.addEventListener('online',updateConnectivity);window.addEventListener('offline',updateConnectivity);
window.addEventListener('popstate',()=>{const view=new URLSearchParams(location.search).get('view')||'home';changeView(view,{history:false});});
(async()=>{try{await ensureSession();await load();render();track('page_view',{view:S.view});if('serviceWorker' in navigator&&location.protocol!=='file:'){const registration=await navigator.serviceWorker.register('/sw.js').catch(()=>null);registration?.addEventListener('updatefound',()=>notify('Доступна новая версия — она применится при следующем запуске.'));}}catch(e){console.error(e);trackError(e,'startup');if(S.userId!=='demo1'){S.userId='demo1';localStorage.setItem('oma-demo-user','demo1');try{await api('/auth/demo','POST',{userId:'demo1'});await load();render();track('page_view',{view:S.view});return;}catch{}}renderFatal(e);}})();
